const body = $json.body ?? {};
let alert;
if (Array.isArray(body.alerts) && body.alerts.length > 0) {
  const a = body.alerts[0];
  alert = {
    namespace: a.labels?.namespace,
    pod: a.labels?.pod,
    alertname: a.labels?.alertname ?? 'PodNotScheduled',
    status: a.status ?? body.status ?? 'firing',
  };
} else {
  alert = {
    namespace: body.namespace,
    pod: body.pod,
    alertname: body.alertname ?? 'PodNotScheduled',
    status: body.status ?? 'firing',
  };
}
const dnsName = /^[a-z0-9]([-a-z0-9]*[a-z0-9])?$/;
for (const key of ['namespace', 'pod']) {
  if (typeof alert[key] !== 'string' || alert[key].length > 253 || !dnsName.test(alert[key])) {
    throw new Error(`alert: field ${key} is missing or is not a valid Kubernetes name`);
  }
}
if (alert.status !== 'firing') {
  throw new Error(`alert: status ${alert.status} is not handled, only firing`);
}
return [{ json: { ...alert, received_at: new Date().toISOString() } }];

const alert = $('Parse alert').first().json;
const j = $input.first().json;
const textOf = (x) => {
  if (!x) return '';
  if (x.structuredContent && typeof x.structuredContent.content === 'string') return x.structuredContent.content;
  if (Array.isArray(x.content)) return x.content.map(c => c.text ?? '').join('\n');
  if (typeof x.content === 'string') return x.content;
  if (typeof x.output === 'string') return x.output;
  return JSON.stringify(x);
};
let podYaml = textOf(j);
const appMatch = podYaml.match(/^\s+app:\s*["']?([a-z0-9][-a-z0-9]*)["']?\s*$/m);
const app = appMatch ? appMatch[1] : alert.pod.replace(/(-[a-f0-9]{5,10}){1,2}$/, '');
let schedulerMessage = '';
const idx = podYaml.indexOf('nodes are available');
if (idx >= 0) {
  const from = podYaml.lastIndexOf('message:', idx);
  const rest = podYaml.slice(from + 'message:'.length);
  const stop = rest.search(/\n\s*(reason|status|type|lastTransitionTime|lastProbeTime):/);
  schedulerMessage = (stop >= 0 ? rest.slice(0, stop) : rest).replace(/\s+/g, ' ').replace(/^['"\s]+|['"\s]+$/g, '');
}
if (podYaml.length > 7000) podYaml = podYaml.slice(0, 7000) + '\n... (обрезано)';
return [{ json: { ...alert, app, scheduler_message: schedulerMessage, pod_yaml: podYaml } }];

const facts = $('Pod facts').first().json;
const textOf = (x) => {
  if (!x) return '';
  if (x.structuredContent && typeof x.structuredContent.content === 'string') return x.structuredContent.content;
  if (Array.isArray(x.content)) return x.content.map(c => c.text ?? '').join('\n');
  if (typeof x.content === 'string') return x.content;
  if (typeof x.output === 'string') return x.output;
  return JSON.stringify(x);
};
const podYaml = facts.pod_yaml;
const eventsRaw = textOf($('Get events').first().json);
const runbook = textOf($('Get runbook').first().json);
const values = textOf($('Get values').first().json);
const deployments = textOf($('Get deployments').first().json);

const chunks = eventsRaw.split(/\n(?=- |\S)/);
let events = chunks.filter(c => c.includes(facts.pod)).join('\n');
if (!events) events = eventsRaw.slice(0, 3000);
if (events.length > 4000) events = events.slice(0, 4000) + '\n... (обрезано)';

const antiKind = (text) => {
  const i = text.indexOf('podAntiAffinity');
  if (i < 0) return 'нет';
  const block = text.slice(i, i + 900);
  if (block.includes('requiredDuringScheduling')) return 'required';
  if (block.includes('preferredDuringScheduling')) return 'preferred';
  return 'есть, тип не распознан';
};
const selectorOf = (text) => {
  const m = text.match(/^\s*nodeSelector:\s*\n((?:\s+[\w./-]+:\s*\S+\n)+)/m);
  if (!m) return text.match(/nodeSelector:\s*\{\s*\}/) || !text.includes('nodeSelector') ? 'нет' : 'есть, не распознан';
  return m[1].trim().split('\n').map(l => l.trim()).join(', ');
};
const requestsOf = (text) => {
  const m = text.match(/requests:\s*\n\s+cpu:\s*(\S+)\s*\n\s+memory:\s*(\S+)/);
  return m ? `cpu ${m[1]}, memory ${m[2]}` : 'не найдено';
};
const valuesAnti = (values.match(/antiAffinity:\s*(\S+)/) || [])[1] || 'нет';
const valuesReplicas = (values.match(/^replicas:\s*(\d+)/m) || [])[1] || '?';
let clusterReplicas = '?';
const nameRe = new RegExp('^\\s*name:\\s*' + facts.app.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*$', 'm');
const nm = deployments.match(nameRe);
if (nm) {
  const after = deployments.slice(nm.index);
  const r = after.match(/replicas:\s*(\d+)/);
  if (r) clusterReplicas = r[1];
}
const nodesTotal = (facts.scheduler_message.match(/0\/(\d+) nodes are available/) || [])[1] || '?';
const tainted = (facts.scheduler_message.match(/(\d+) node\(s\) had untolerated taint/) || [])[1] || '0';
const workers = nodesTotal === '?' ? '?' : String(Number(nodesTotal) - Number(tainted));

const cluster = { replicas: clusterReplicas, anti: antiKind(podYaml), selector: selectorOf(podYaml), requests: requestsOf(podYaml) };
const repo = { replicas: valuesReplicas, anti: valuesAnti, selector: selectorOf(values), requests: requestsOf(values) };
const row = (title, a, b) => `- ${title}: в кластере ${a}, в values ${b}: ${a === b ? 'совпадает' : 'ОТЛИЧАЕТСЯ'}`;
const comparison = [
  row('replicas деплоймента', cluster.replicas, repo.replicas),
  row('podAntiAffinity', cluster.anti, repo.anti),
  row('nodeSelector', cluster.selector, repo.selector),
  row('requests', cluster.requests, repo.requests),
  `- нод в кластере ${nodesTotal}, из них с taint (не для нагрузки) ${tainted}, воркеров ${workers}`,
].join('\n');

const context = [
  `### Сравнение манифеста в кластере с values.yaml из репозитория, посчитано workflow`,
  comparison,
  `### Сообщение планировщика, извлечено из status.conditions`,
  facts.scheduler_message || '(не найдено, смотри события)',
  `### Под ${facts.namespace}/${facts.pod}, результат pods_get`,
  '```yaml', podYaml, '```',
  `### События namespace ${facts.namespace}, результат events_list, отфильтровано по поду`,
  '```', events, '```',
  '### /knowledge/runbook-pending-pods.md',
  runbook,
  `### /knowledge/services/${facts.app}/values.yaml`,
  '```yaml', values, '```',
].join('\n');
return [{ json: { ...facts, cluster, repo, workers, comparison, context } }];

const agent = $input.first().json;
const request = $('Parse alert').first().json;
const facts = $('Pod facts').first().json;
let text = agent.output ?? agent.text ?? '';
if (typeof text !== 'string') text = JSON.stringify(text);
text = text.replace(/<think>[\s\S]*?<\/think>/g, '');
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start < 0 || end <= start) throw new Error('verdict: agent output has no JSON object');
let v;
try {
  v = JSON.parse(text.slice(start, end + 1));
} catch (e) {
  throw new Error('verdict: agent output is not valid JSON: ' + e.message);
}
const categories = ['anti_affinity', 'insufficient_resources', 'node_selector', 'taints', 'volume', 'other'];
if (!categories.includes(v.category)) throw new Error('verdict: unknown category ' + JSON.stringify(v.category));
for (const key of ['scheduler_message', 'recommendation']) {
  if (typeof v[key] !== 'string' || !v[key].trim()) throw new Error('verdict: ' + key + ' must be a non-empty string');
}
const asLine = (x) => {
  if (typeof x === 'string') return x.trim();
  if (x && typeof x === 'object') return Object.values(x).filter(y => typeof y === 'string' && y.trim()).join(' | ');
  return String(x ?? '');
};
const asList = (x) => {
  if (x === undefined || x === null) return [];
  if (typeof x === 'string') return x.trim() ? [x] : [];
  if (Array.isArray(x)) return x.map(asLine).filter(y => y);
  if (typeof x === 'object') return Object.entries(x).map(([k, y]) => `${k}: ${asLine(y)}`).filter(y => y);
  return [String(x)];
};
v.evidence = asList(v.evidence);
if (v.evidence.length === 0) throw new Error('verdict: evidence must not be empty');
const known = [
  `pods_get ${request.namespace}/${request.pod}`,
  `events_list ${request.namespace}`,
  `resources_list apps/v1 Deployment ${request.namespace}`,
  '/knowledge/runbook-pending-pods.md',
  `/knowledge/services/${facts.app}/values.yaml`,
];
v.sources = asList(v.sources);
for (const k of known) if (!v.sources.some(s => s.includes(k))) v.sources.push(k);
for (const key of ['drift', 'rule_violation']) {
  if (v[key] === undefined || v[key] === null || v[key] === '') { v[key] = null; continue; }
  if (Array.isArray(v[key])) v[key] = v[key].map(asLine).filter(x => x).join('; ');
  else if (typeof v[key] === 'object') v[key] = Object.entries(v[key]).map(([k, x]) => `${k}: ${asLine(x)}`).join('; ');
  else v[key] = String(v[key]);
  if (/^(null|none|нет|n\/a)$/i.test(v[key].trim())) v[key] = null;
}
const message = (facts.scheduler_message || v.scheduler_message).toLowerCase();
let derived = 'other';
if (message.includes('anti-affinity')) derived = 'anti_affinity';
else if (message.includes('insufficient')) derived = 'insufficient_resources';
else if (message.includes('node affinity') || message.includes('node selector') || message.includes('nodeselector')) derived = 'node_selector';
else if (message.includes('volume') || message.includes('persistentvolumeclaim')) derived = 'volume';
else if (message.includes('taint')) derived = 'taints';
if (derived !== 'other' && v.category !== derived) {
  v.evidence.push(`Категория исправлена кодом: модель предложила ${v.category}, по сообщению планировщика это ${derived}`);
  v.category = derived;
}
if (facts.scheduler_message) {
  const norm = (t) => t.replace(/\s+/g, ' ').trim().toLowerCase();
  const expected = norm(facts.scheduler_message).slice(0, 40);
  if (!norm(v.scheduler_message).includes(expected)) throw new Error('verdict: scheduler_message differs from status.conditions of the pod');
}
const verdict = {
  namespace: request.namespace,
  pod: request.pod,
  alertname: request.alertname,
  category: v.category,
  scheduler_message: v.scheduler_message,
  evidence: v.evidence,
  drift: v.drift || null,
  rule_violation: v.rule_violation || null,
  recommendation: v.recommendation,
  sources: v.sources,
};
const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
const fileName = `${stamp}-${request.namespace}-${request.pod}.md`;
const lines = [
  `# Pending: ${request.namespace}/${request.pod}`,
  '',
  `Алерт: ${request.alertname}. Категория: ${verdict.category}.`,
  '',
  '## Что сказал планировщик',
  '',
  verdict.scheduler_message,
  '',
  '## Доказательства',
  '',
  ...verdict.evidence.map(e => `- ${e}`),
  '',
];
if (verdict.drift) lines.push('## Расхождение с репозиторием', '', verdict.drift, '');
if (verdict.rule_violation) lines.push('## Нарушено правило размещения', '', verdict.rule_violation, '');
lines.push('## Что сделать', '', verdict.recommendation, '', '## Источники', '', ...verdict.sources.map(s => `- ${s}`), '');
const markdown = lines.join('\n');
return [{
  json: { ...verdict, file: '/files/' + fileName },
  binary: { report: { data: Buffer.from(markdown, 'utf8').toString('base64'), mimeType: 'text/markdown', fileName } },
}];
